    /**
     * [AI-GENERATED: Claude Code]
     * Test that the anatomy selector panel loads correctly
     */
    #[Test]
    public function testAnatomySelectorLoads(): void
    {
        // Login as admin
        $this->login(LoginTestData::username, LoginTestData::password);

        // Navigate to patient chart
        $this->navigateToPatientEncounter();

        // Open Vietnamese PT Assessment form
        $this->openPTAssessmentForm();

        // Wait for anatomy selector container to be present
        $this->client->wait(10)->until(function ($driver) {
            $elements = $driver->findElements(WebDriverBy::id('anatomy-selector'));
            return count($elements) > 0;
        });

        $this->crawler = $this->client->refreshCrawler();

        // Verify anatomy selector panel is visible
        $anatomySelector = $this->crawler->filter('#anatomy-selector');
        $this->assertGreaterThan(0, $anatomySelector->count(), 'Anatomy selector panel should be present');

        // Verify "Chọn vùng giải phẫu" heading exists
        $cardHeader = $this->crawler->filter('.card-header h5');
        $this->assertGreaterThan(0, $cardHeader->count(), 'Card header should be present');
        $headerText = $cardHeader->text();
        $this->assertTrue(
            str_contains($headerText, 'Chọn vùng giải phẫu') ||
            str_contains($headerText, 'Anatomical Region Selection'),
            'Header should contain anatomy selector title'
        );

        // Verify body SVG image loads
        $this->client->wait(10)->until(function ($driver) {
            $elements = $driver->findElements(WebDriverBy::cssSelector('#anatomy-selector svg'));
            return count($elements) > 0;
        });

        $this->crawler = $this->client->refreshCrawler();
        $svg = $this->crawler->filter('#anatomy-selector svg');
        $this->assertGreaterThan(0, $svg->count(), 'Body SVG should be loaded');
    }

    /**
     * [AI-GENERATED: Claude Code]
     * Test front/back view toggle functionality
     */
    #[Test]
    #[Depends('testAnatomySelectorLoads')]
    public function testFrontBackViewToggle(): void
    {
        $this->login(LoginTestData::username, LoginTestData::password);
        $this->navigateToPatientEncounter();
        $this->openPTAssessmentForm();

        // Wait for anatomy selector to load
        $this->waitForAnatomySelector();

        $this->crawler = $this->client->refreshCrawler();

        // Verify "Mặt trước" (Front) button is active by default
        $frontButton = $this->crawler->filter('.view-btn[data-view="front"]');
        $this->assertGreaterThan(0, $frontButton->count(), 'Front view button should exist');

        $frontButtonClass = $frontButton->attr('class');
        $this->assertStringContainsString('active', $frontButtonClass, 'Front view button should be active by default');

        // Click "Mặt sau" (Back) button
        $backButton = $this->crawler->filter('.view-btn[data-view="back"]');
        $this->assertGreaterThan(0, $backButton->count(), 'Back view button should exist');
        $backButton->click();

        // Wait for SVG to reload
        $this->client->wait(5)->until(function ($driver) {
            // Check if loading indicator is gone or new SVG is loaded
            $loadingElements = $driver->findElements(WebDriverBy::cssSelector('.anatomy-loading'));
            return count($loadingElements) === 0;
        });

        sleep(1); // Additional wait for SVG rendering

        $this->crawler = $this->client->refreshCrawler();

        // Verify back view button is now active
        $backButtonAfter = $this->crawler->filter('.view-btn[data-view="back"]');
        $backButtonClass = $backButtonAfter->attr('class');
        $this->assertStringContainsString('active', $backButtonClass, 'Back view button should be active after click');

        // Click "Mặt trước" button again
        $frontButtonAgain = $this->crawler->filter('.view-btn[data-view="front"]');
        $frontButtonAgain->click();

        // Wait for SVG to reload
        $this->client->wait(5)->until(function ($driver) {
            $loadingElements = $driver->findElements(WebDriverBy::cssSelector('.anatomy-loading'));
            return count($loadingElements) === 0;
        });

        sleep(1);

        $this->crawler = $this->client->refreshCrawler();

        // Verify front view is active again
        $frontButtonFinal = $this->crawler->filter('.view-btn[data-view="front"]');
        $frontButtonFinalClass = $frontButtonFinal->attr('class');
        $this->assertStringContainsString('active', $frontButtonFinalClass, 'Front view button should be active again');
    }

    /**
     * [AI-GENERATED: Claude Code]
     * Test layer toggle checkboxes
     */
    #[Test]
    #[Depends('testAnatomySelectorLoads')]
    public function testLayerToggles(): void
    {
        $this->login(LoginTestData::username, LoginTestData::password);
        $this->navigateToPatientEncounter();
        $this->openPTAssessmentForm();

        $this->waitForAnatomySelector();

        $this->crawler = $this->client->refreshCrawler();

        // Verify layer checkboxes exist
        $layerCheckboxes = $this->crawler->filter('.anatomy-layers input[type="checkbox"]');
        $this->assertGreaterThan(0, $layerCheckboxes->count(), 'Layer toggle checkboxes should exist');

        // Expected layers: Cơ (Muscle), Xương (Bone), Khớp (Joint), Dây chằng (Ligament), Gân (Tendon), Thần kinh (Nerve), Mạch máu (Vessel)
        $expectedLayers = ['muscle', 'bone', 'joint', 'ligament', 'tendon', 'nerve', 'vessel'];

        foreach ($expectedLayers as $layer) {
            $checkbox = $this->crawler->filter('input[data-layer="' . $layer . '"]');
            $this->assertGreaterThan(0, $checkbox->count(), "Checkbox for layer '{$layer}' should exist");
        }

        // Test unchecking "Cơ" (Muscle) checkbox
        $muscleCheckbox = $this->crawler->filter('input[data-layer="muscle"]');
        if ($muscleCheckbox->count() > 0) {
            $isChecked = $muscleCheckbox->getElement(0)->isSelected();

            if ($isChecked) {
                // Uncheck the muscle layer
                $muscleCheckbox->click();

                // Wait a moment for the change to apply
                sleep(1);

                $this->crawler = $this->client->refreshCrawler();

                // Verify muscle layer checkbox is now unchecked
                $muscleCheckboxAfter = $this->crawler->filter('input[data-layer="muscle"]');
                $isCheckedAfter = $muscleCheckboxAfter->getElement(0)->isSelected();
                $this->assertFalse($isCheckedAfter, 'Muscle checkbox should be unchecked');

                // Check "Cơ" checkbox again
                $muscleCheckboxAfter->click();

                sleep(1);

                $this->crawler = $this->client->refreshCrawler();

                // Verify muscle layer is visible again
                $muscleCheckboxFinal = $this->crawler->filter('input[data-layer="muscle"]');
                $isCheckedFinal = $muscleCheckboxFinal->getElement(0)->isSelected();
                $this->assertTrue($isCheckedFinal, 'Muscle checkbox should be checked again');
            }
        }
    }

